import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    # The samples begin with numeric data, not column labels.
    with io.StringIO(raw_csv, newline="") as stream:
        rows = list(csv.reader(stream, delimiter=",", quotechar='"', doublequote=True))

    width = max(2, max((len(row) for row in rows), default=0))
    columns = [f"column_{index}" for index in range(1, width + 1)]
    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
